from dataclasses import dataclass
from typing import Optional, Any, Callable

class Depends:
    dependency: Optional[Callable] = None
    use_cache: bool = True
    scope: Optional[str] = None

    def __eq__(self, other):
        if not isinstance(other, Depends):
            return NotImplemented
        return (
            self.dependency == other.dependency and
            self.use_cache == other.use_cache and
            self.scope == other.scope
        )

    def __hash__(self):
        return hash((self.dependency, self.use_cache, self.scope))

@dataclass(frozen=True)
class Security(Depends):
    scopes: Optional[list] = None

def test():
    d1 = Depends()
    d2 = Depends()
    print(f"Depends equal: {d1 == d2}")
    print(f"Depends hash: {hash(d1)}")

    s1 = Security(scopes=["read"])
    s2 = Security(scopes=["read"])
    print(f"Security equal: {s1 == s2}")
    print(f"Security hash: {hash(s1)}")

    s3 = Security(scopes=["write"])
    print(f"Security equal s1 vs s3: {s1 == s3}")

if __name__ == "__main__":
    test()

